<section class="page-hero compact"><div class="container"><span class="eyebrow">Administrator</span><h1>Post Management</h1><p>Edit, unpublish or delete destination posts.</p></div></section>
<section class="section container"><div class="table-wrap panel-table"><table><thead><tr><th>Title</th><th>Country</th><th>Scout</th><th>Cost</th><th>Published</th><th>Actions</th></tr></thead><tbody><?php foreach($posts as $row): ?><tr><td><?= e($row['title']) ?></td><td><?= e($row['country']) ?></td><td><?= e($row['scout_name'] ?? 'Deleted Scout') ?></td><td><?= e($row['cost_level']) ?></td><td><?= (int)$row['is_approved']===1?'<span class="verified-pill">Yes</span>':'<span class="pending-pill">No</span>' ?></td><td><div class="table-actions"><a class="btn btn-soft btn-sm" href="<?= e(url('admin/post/edit',['id'=>$row['id']])) ?>">Edit</a><?php if((int)$row['is_approved']===1): ?><a class="btn btn-dark btn-sm" href="<?= e(url('post',['id'=>$row['id']])) ?>">View</a><?php endif; ?><form method="post" action="<?= e(url('admin/post/delete')) ?>" onsubmit="return confirm('Delete this post and its comments/wishlists?')"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><button class="btn btn-danger btn-sm" type="submit">Delete</button></form></div></td></tr><?php endforeach; ?></tbody></table></div></section>
